import { execFile } from 'node:child_process';
import { createHash } from 'node:crypto';
import { copyFile, mkdir, mkdtemp, readFile, rm, symlink, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { promisify } from 'node:util';
import { isolatedDatabase } from '../../../apps/server/src/operations/database.js';

const run = promisify(execFile);
const sourceCommit = 'b5258d974c905ae6c621ed52fba6e8b5889aa7e7';
const destination = 'tests/fixtures/historical/008';
const sha256 = (value: string | Buffer) => createHash('sha256').update(value).digest('hex');
const databaseUrl = process.env.TEST_DATABASE_URL;
if (!databaseUrl) throw new Error('TEST_DATABASE_URL must allow isolated database creation.');
await mkdir('.local', { recursive: true, mode: 0o700 });
const temporary = await mkdtemp('.local/historical-source-');
const source = `${temporary}/source`;
let database: Awaited<ReturnType<typeof isolatedDatabase>> | undefined;
try {
  await mkdir(source);
  await run('git', ['archive', `--output=${temporary}/source.tar`, sourceCommit]);
  await run('tar', ['-xf', `${temporary}/source.tar`, '-C', source]);
  const lockfile = await readFile(`${source}/pnpm-lock.yaml`);
  const installedLockfile = await readFile('pnpm-lock.yaml');
  const dependencyGraph = (value: Buffer) => {
    const text = value.toString('utf8');
    const index = text.indexOf('\npackages:\n');
    if (index < 0) throw new Error('Unsupported historical lockfile format.');
    return text.slice(index);
  };
  if (dependencyGraph(lockfile) !== dependencyGraph(installedLockfile))
    throw new Error(
      'Historical transitive dependency graph changed. Install the archived lockfile instead.',
    );
  // Reuse installed external dependencies only when every historical package
  // dependency is still exactly pinned. Workspace aliases are explicitly bound
  // to the archived source so the current application cannot seed the fixture.
  const packages = [
    '.',
    'apps/server',
    'packages/database',
    'packages/domain',
    'packages/contracts',
  ];
  const packageDependencies: Record<string, Record<string, string>> = {};
  for (const directory of packages) {
    const historical = JSON.parse(await readFile(`${source}/${directory}/package.json`, 'utf8'));
    const current = JSON.parse(await readFile(`${directory}/package.json`, 'utf8'));
    const dependencies = { ...historical.dependencies, ...historical.devDependencies };
    packageDependencies[directory] = dependencies;
    const currentDependencies = { ...current.dependencies, ...current.devDependencies };
    const modules = `${source}/${directory}/node_modules`;
    await mkdir(modules, { recursive: true });
    for (const [name, version] of Object.entries(dependencies)) {
      if (name.startsWith('@sandbox/')) {
        await mkdir(`${modules}/@sandbox`, { recursive: true });
        await symlink(
          resolve(`${source}/packages/${name.slice('@sandbox/'.length)}`),
          `${modules}/${name}`,
        );
      } else {
        if (currentDependencies[name] !== version)
          throw new Error(
            `Historical dependency changed: ${name}. Install the archived lockfile instead.`,
          );
        const installed = JSON.parse(
          await readFile(`${directory}/node_modules/${name}/package.json`, 'utf8'),
        );
        if (installed.version !== version)
          throw new Error(`Installed historical dependency version does not match: ${name}.`);
        if (name.startsWith('@'))
          await mkdir(`${modules}/${name.split('/')[0]}`, { recursive: true });
        await symlink(resolve(`${directory}/node_modules/${name}`), `${modules}/${name}`);
      }
    }
  }
  await copyFile('tests/fixtures/historical/seed-008.mjs', `${source}/historical-seed.mjs`);
  database = await isolatedDatabase(databaseUrl);
  const output = `${temporary}/seed.json`;
  await run(process.execPath, ['--import', 'tsx', 'historical-seed.mjs'], {
    cwd: source,
    env: {
      ...process.env,
      HISTORICAL_DATABASE_URL: database.url,
      HISTORICAL_OUTPUT_PATH: resolve(output),
    },
    maxBuffer: 1024 * 1024,
  });
  const seeded = JSON.parse(await readFile(output, 'utf8')) as {
    migrations: [string, string][];
    tables: string[];
    data: Record<string, string[]>;
    sequences: { name: string; lastValue: string; isCalled: boolean }[];
    version: string;
    expectations: unknown;
  };
  // JSON record loading retains PostgreSQL's exact numeric and microsecond
  // timestamp representations. No financial value passes through JS Number.
  const schema = seeded.migrations
    .map(([name, statement]) => `-- ${name}\n${statement}`)
    .join('\n');
  const fixture = [
    '-- Synthetic fixture generated by the archived008 application. Never load into a live database.',
    'BEGIN;',
    'CREATE TABLE schema_migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);',
    schema,
    ...seeded.tables.map((table) => `ALTER TABLE ${table} DISABLE TRIGGER USER;`),
    'DELETE FROM exchange_control;',
    ...seeded.tables.map((table) => {
      const rows = `[${seeded.data[table]!.join(',')}]`;
      if (rows.includes('$fixture$')) throw new Error('Fixture delimiter collision.');
      return `INSERT INTO ${table} OVERRIDING SYSTEM VALUE SELECT * FROM json_populate_recordset(NULL::${table}, $fixture$${rows}$fixture$::json);`;
    }),
    ...seeded.sequences.map(({ name, lastValue, isCalled }) => {
      if (!/^[a-z_]+$/.test(name) || !/^\d+$/.test(lastValue))
        throw new Error('Invalid historical sequence.');
      return `SELECT setval('${name}', '${lastValue}'::bigint, ${isCalled});`;
    }),
    'SET CONSTRAINTS ALL IMMEDIATE;',
    ...seeded.tables.map((table) => `ALTER TABLE ${table} ENABLE TRIGGER USER;`),
    'COMMIT;\n',
  ].join('\n');
  await mkdir(destination, { recursive: true });
  await writeFile(`${destination}/installation.sql`, fixture);
  await writeFile(
    `${destination}/expectations.json`,
    `${JSON.stringify(seeded.expectations, null, 2)}\n`,
  );
  await writeFile(
    `${destination}/manifest.json`,
    `${JSON.stringify(
      {
        formatVersion: 1,
        sourceCommit,
        historicalLockfileSha256: sha256(lockfile),
        reusedLockfileSha256: sha256(installedLockfile),
        dependencyGraphSha256: sha256(dependencyGraph(lockfile)),
        packageDependencies,
        builderSha256: sha256(await readFile('tests/fixtures/historical/seed-008.mjs')),
        generatorSha256: sha256(await readFile('tests/fixtures/historical/generate.ts')),
        postgresVersion: seeded.version.match(/^\d+(?:\.\d+)*/)?.[0],
        installationSha256: sha256(fixture),
        expectationsSha256: sha256(`${JSON.stringify(seeded.expectations, null, 2)}\n`),
        migrationStatements: seeded.migrations.map(([name, statement]) => ({
          name,
          sha256: sha256(statement),
        })),
        rows: Object.fromEntries(seeded.tables.map((table) => [table, seeded.data[table]!.length])),
        sequences: seeded.sequences,
        sanitization:
          'Synthetic data only. Credential hashes disabled; login sessions removed. No usable secrets.',
      },
      null,
      2,
    )}\n`,
  );
  console.log(
    `Frozen008 fixture regenerated from ${sourceCommit}. Review and retain its manifest hashes.`,
  );
} finally {
  try {
    await database?.dispose();
  } finally {
    await rm(temporary, { recursive: true, force: true });
  }
}
